    entryFeeKn: "\u0CB8\u0CBE\u0CAE\u0CBE\u0CA8\u0CCD\u0CAF \u0CA6\u0CB0\u0CCD\u0CB6\u0CA8: \u0C89\u0C9A\u0CBF\u0CA4 | \u0CB5\u0CBF\u0CB6\u0CC7\u0CB7 \u0CA6\u0CB0\u0CCD\u0CB6\u0CA8 \u0CB6\u0CC1\u0CB2\u0CCD\u0C95 \u0CAA\u0CCD\u0CB0\u0CA4\u0CCD\u0CAF\u0CC7\u0C95",
